def countBinarySubarrays(nums, goal):
    def at_most(g):
        if g < 0:
            return 0
        left = 0
        cur = 0
        total = 0
        for right, x in enumerate(nums):
            cur += x
            while cur > g:
                cur -= nums[left]
                left += 1
            total += right - left + 1
        return total
    return at_most(goal) - at_most(goal - 1)
